    l1 = [np.float32(0.0)]*4
    pre4 = 4 if ml & 4 else 0
    if pre4:
        for t in range(4):
            l0[t] = fmaf(a[off+t], x[off+t], l0[t])
    i = off + pre4
    while i < off + ml:
        for t in range(4):
            l0[t] = fmaf(a[i+t], x[i+t], l0[t])
        for t in range(4):
            l1[t] = fmaf(a[i+4+t], x[i+4+t], l1[t])
        i += 8
    s0 = l1[0]+l0[0]; s1 = l1[1]+l0[1]; s2 = l1[2]+l0[2]; s3 = l1[3]+l0[3]
    return (s0+s1)+(s2+s3)

