def fmaf(a, b, c):
    return np.float32(math.fma(float(a), float(b), float(c)))
def mul(a, b):
    return np.float32(float(a)*float(b))

def trees(l, r):
    # all binary trees over leaves l..r-1, as expressions over p[]
    if r - l == 1:
        yield ('p%d' % l), None
        return
    for m in range(l+1, r):
        for e1, _ in trees(l, m):
            for e2, _ in trees(m, r):
                yield ('(%s+%s)' % (e1, e2)), None

def evaltree(expr, p):
    stack = []
    i = 0
    for ch in expr:
        if ch == 'p':
            stack.append(p[int(expr[i+1]) if expr[i+2] in '+()' else int(expr[i+1:i+2])])
    # simpler: use eval with p as locals
    return eval(expr, {}, {'p': p})

